const item = $input.first().json;
const body = item.text || item.snippet || item.body || '';
const subject = item.subject || '';

// Extract amount — matches patterns like:
// SGD 123.45  /  S$123.45  /  SGD123.45  /  $123.45
const amountMatch = body.match(/(?:SGD|S\$|\$)[\s]?([\d,]+\.?\d{0,2})/i) ||
                    subject.match(/(?:SGD|S\$|\$)[\s]?([\d,]+\.?\d{0,2})/i);
const amount = amountMatch ? amountMatch[1].replace(/,/g, '') : 'N/A';

// Extract date — matches DD/MM/YYYY, DD MMM YYYY, DD-MM-YYYY, YYYY-MM-DD
const dateMatch = body.match(/(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/) ||
                  body.match(/(\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\w*\s+\d{4})/i) ||
                  body.match(/(\d{4}-\d{2}-\d{2})/);
const rawDate = dateMatch ? dateMatch[1] : '';

// Normalise to DD/MM/YYYY
let txDate = rawDate;
if (/\d{4}-\d{2}-\d{2}/.test(rawDate)) {
  const [y, m, d] = rawDate.split('-');
  txDate = d + '/' + m + '/' + y;
}

// Extract last 4 digits of account/card if present
const acctMatch = body.match(/account\s+(?:ending\s+)?(?:no[\.:]*\s+)?[Xx*]+(\d{4})/i) ||
                  body.match(/\*+(\d{4})/i);
const acctLast4 = acctMatch ? acctMatch[1] : 'N/A';

// Detect transaction type
let txType = 'Unknown';
if (/debit|debited|purchase|payment|paid/i.test(body)) txType = 'Debit';
else if (/credit|credited|received|deposit/i.test(body)) txType = 'Credit';

// Capture received timestamp (Singapore time)
const now = new Date();
const sg = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Singapore' }));
const receivedAt = sg.toLocaleString('en-SG', { timeZone: 'Asia/Singapore' });

return [{ json: {
  email_subject: subject,
  email_date: item.date || '',
  received_at: receivedAt,
  tx_date: txDate || receivedAt.split(',')[0],
  amount: amount,
  tx_type: txType,
  acct_last4: acctLast4,
  email_body_preview: body.substring(0, 300)
} }];
